  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    edges = []
    for a, b, d in distances:
        if a > b:
            a, b = b, a
        w = max(core_dist[a], core_dist[b], d)
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    parent = list(range(len(nodes)))
    rank = [0] * len(nodes)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(node_to_idx[a], node_to_idx[b]):
            mst_edges.append([a, b, w])
            total_weight += w
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
